def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    rem = 100 - n
    if rem <= 0:
        return 'C'
    if rem == 1:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    my_score = 0
    opp_score = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    overall_opp = opp_c / n
    r10 = min(10, n)
    recent10 = sum(1 for _, b in history[-r10:] if b == 'C') / r10
    r20 = min(20, n)
    recent20 = sum(1 for _, b in history[-r20:] if b == 'C') / r20
    score_diff = my_score - opp_score

    opp_d_streak = 0
    for _, b in reversed(history):
        if b == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    perfect_coop = (opp_c == n and my_c == n)

    def sidx(a, b):
        return (0 if a == 'C' else 1) * 2 + (0 if b == 'C' else 1)

    cur = sidx(last_me, last_opp)

    trans = [[0, 0] for _ in range(4)]
    after_d_total = 0
    after_d_coop = 0
    after_c_total = 0
    after_c_coop = 0
    for i in range(n - 1):
        a, b = history[i]
        st = sidx(a, b)
        nb = history[i + 1][1]
        if nb == 'C':
            trans[st][0] += 1
        else:
            trans[st][1] += 1
        if a == 'D':
            after_d_total += 1
            if nb == 'C':
                after_d_coop += 1
        else:
            after_c_total += 1
            if nb == 'C':
                after_c_coop += 1

    if after_d_total == 0:
        if perfect_coop:
            after_d_est = 0.32
        elif overall_opp > 0.80:
            after_d_est = 0.20
        elif overall_opp > 0.50:
            after_d_est = 0.13
        else:
            after_d_est = 0.08
    else:
        after_d_est = (after_d_coop + 0.5) / (after_d_total + 1.5)

    if after_c_total == 0:
        if overall_opp > 0.80:
            after_c_est = 0.72
        elif overall_opp > 0.45:
            after_c_est = 0.52
        else:
            after_c_est = 0.24
    else:
        after_c_est = (after_c_coop + 0.5) / (after_c_total + 1.5)

    LATE = 10
    if rem <= LATE:
        def clamp(p):
            if p < 0.03:
                return 0.03
            if p > 0.97:
                return 0.97
            return p

        def prior(st):
            if st == 0:
                if perfect_coop and overall_opp > 0.97:
                    base = 0.95
                else:
                    base = 0.16 + 0.72 * max(overall_opp, recent20)
                    if recent10 > 0.90:
                        base += 0.05
                return clamp(base)

            if st == 1:
                if overall_opp > 0.82 and recent10 > 0.45:
                    base = 0.48 + 0.34 * after_c_est
                elif overall_opp > 0.50:
                    base = 0.36 + 0.30 * after_c_est
                else:
                    base = 0.18 + 0.26 * after_c_est
                return clamp(base)

            if st == 2:
                base = 0.10 + 0.74 * after_d_est
                return clamp(base)

            base = 0.07 + 0.46 * after_d_est + 0.14 * overall_opp
            return clamp(base)

        def pstate(st):
            c = trans[st][0]
            d = trans[st][1]
            total = c + d
            base = prior(st)
            if total == 0:
                return base
            if st == 2 or st == 3:
                if total <= 2:
                    alpha = 2.5
                else:
                    alpha = 1.2
            else:
                if total <= 4:
                    alpha = 2.0
                else:
                    alpha = 1.0
            return clamp((c + alpha * base) / (total + alpha))

        pcs = [pstate(0), pstate(1), pstate(2), pstate(3)]

        memo_val = [[0.0] * 101 for _ in range(4)]
        memo_seen = [[False] * 101 for _ in range(4)]

        def val(st, r):
            if r <= 0:
                return 0.0
            if memo_seen[st][r]:
                return memo_val[st][r]
            p = pcs[st]
            if r == 1:
                res = 1.0 + 4.0 * p
            else:
                vc = p * (3.0 + val(0, r - 1)) + (1.0 - p) * val(1, r - 1)
                vd = p * (5.0 + val(2, r - 1)) + (1.0 - p) * (1.0 + val(3, r - 1))
                if vc >= vd:
                    res = vc
                else:
                    res = vd
            memo_val[st][r] = res
            memo_seen[st][r] = True
            return res

        def dp_action(st, r):
            if r == 1:
                return 'D'
            p = pcs[st]
            vc = p * (3.0 + val(0, r - 1)) + (1.0 - p) * val(1, r - 1)
            vd = p * (5.0 + val(2, r - 1)) + (1.0 - p) * (1.0 + val(3, r - 1))
            if vd > vc + 0.000001:
                return 'D'
            return 'C'

        action = dp_action(cur, rem)
        if rem == 2 and last_opp == 'C' and recent10 > 0.58 and overall_opp > 0.45:
            action = 'D'
        return action

    if overall_opp < 0.25 and recent10 < 0.30:
        if dd_streak >= 12 and rng.random() < 0.02:
            return 'C'
        return 'D'

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    if perfect_coop and 45 <= n <= 70 and rng.random() < 0.045:
        return 'D'

    if (overall_opp > 0.96 and recent20 > 0.95 and after_d_total >= 2 and after_d_coop >= 2
            and last_opp == 'C' and n < 85 and rng.random() < 0.035):
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_d_streak >= 3:
                if recent20 > 0.22 and after_c_est > 0.42:
                    if rng.random() < 0.30:
                        return 'C'
                elif overall_opp > 0.60 and recent10 > 0.28:
                    if rng.random() < 0.22:
                        return 'C'
                return 'D'

            if opp_d_streak >= 2:
                if recent10 < 0.22:
                    return 'D'
                if rng.random() < 0.18:
                    return 'C'
                return 'D'

            if overall_opp > 0.38 or recent10 > 0.24:
                return 'C'
            return 'D'

        else:
            if opp_d_streak >= 2:
                return 'D'
            if overall_opp > 0.70 and recent10 > 0.42 and after_c_est > 0.34:
                return 'C'
            if score_diff > 10 and recent10 > 0.30:
                return 'C'
            if score_diff < -10 and recent10 < 0.55:
                return 'D'
            if rng.random() < 0.45:
                return 'D'
            return 'C'

    if last_me == 'D':
        if after_d_total >= 1 and after_d_est > 0.70 and recent20 > 0.90 and rng.random() < 0.10:
            return 'D'
        return 'C'

    if score_diff < -18 and recent10 > 0.45 and rng.random() < 0.15:
        return 'D'

    return 'C'
